import{_ as s,l,o as e,c as o,v as t,p as n,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"哈希索引","description":"","frontmatter":{"title":"哈希索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hash-index.md","filePath":"cs/hash-index.md","lastUpdated":1789023840000}'),c={name:"cs/hash-index.md"};function B(E,a,_,m,u,f){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="哈希索引" tabindex="-1">哈希索引 <a class="header-anchor" href="#哈希索引" aria-label="Permalink to &quot;哈希索引&quot;">​</a></h1><div class="epigraph"><p>等值查找可以把键打散到桶；范围与有序扫描它给不了，那是 B+ 的工作。</p><footer>—— 据 Fagin et al., Extendible Hashing, TODS 1979；Litwin 线性哈希整理</footer></div><p><a href="/cs/bplus-split">上一课</a>把范围与有序交给 B+ 叶链。本课不重画叶分裂。缺口是：许多谓词是纯等值（主键点查、等值连接探针）。哈希桶把期望 I/O 压到接近常数，但丢掉序。<a href="/cs/hash-function">数据结构</a>已有散列函数；这里要的是可增长的<strong>磁盘桶</strong>，不是内存一张表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>B+ 点查仍走树高。哈希索引用 \\(h(k)\\) 选桶页，桶内再找。缺口不是再讲链地址，而是外存上桶会满、目录会扩：可扩展哈希用目录倍增，线性哈希用渐进分裂。本课不把这两种目录结构证完，只锁定：等值 \\(O(1)\\) 页级期望，范围查询不走它。</p><p><span class="marginnote">静态哈希在表增长后溢出链变长，退化为扫描。库用可扩展或线性哈希，使桶数随记录数长，而不是一次性定死桶数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>可扩展哈希：目录是全局深度下的指针数组，桶有局部深度；满则分裂，必要时目录翻倍。线性哈希：按回合依次分裂桶，指针沿桶号走，避免一次翻倍。桶页仍是<a href="/cs/page-slot">槽化页</a>。哈希连接用的内存表与本课磁盘索引同族不同场景：一个是算子工作区，一个是持久访问路径。</p>',8)),(e(),n(h,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E9%94%AE%20k%22%5D%20--%3E%20H%5B%22h(k)%22%5D%0A%20%20H%20--%3E%20BUCKET%5B%22%E6%A1%B6%E9%A1%B5%22%5D%0A%20%20BUCKET%20--%3E%20EQ%5B%22%E7%AD%89%E5%80%BC%E5%91%BD%E4%B8%AD%22%5D%0A%20%20EQ%20--%3E%20WAL%5B%22%E5%90%8E%E8%AF%BE%3A%20WAL%22%5D%0A%20%20BPLUS%5B%22B%2B%20%E5%8F%B6%E9%93%BE%22%5D%20--%3E%20RNG%5B%22%E8%8C%83%E5%9B%B4%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>等值连接的内层若有哈希索引，索引嵌套循环变成探针桶；这与一次性哈希连接（建临时表）互补。唯一性约束同样可落在哈希桶上，只是无法支持 <code>BETWEEN</code>。倾斜键把许多行打进同一桶，溢出链变长，估计里的「常数」被打穿——独立于 B+ 的倾斜（那是叶页热）。</p><p>本课不把布隆过滤器当索引：过滤器可判「一定不在」，不能给出 rid 列表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲一致性哈希做分布式分片，那是系统扩展，不是本课的页桶。也不把加密哈希（后课安全）与索引哈希混名：一个抗碰撞，一个要快、要均匀。崩溃后目录与桶页必须一起恢复，入口在下一课 WAL。</p><p>等值连接的选择率若高，哈希索引的「点查」会退化成扫很多溢出页，代价模型必须改用基数而不是「一次 I/O」。后课默认：等值可走哈希或 B+；有序、范围、排序只认 B+（或显式排序算子）。</p><p>桶目录本身也是页，会脏、要记日志。可增长哈希不是「无结构的数组」，崩溃与并发与 B+ 同一家族。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>范围、排序、<code>ORDER BY</code> 不走哈希桶；优化器若选错，是代价问题。</p></li><li><p>后课 WAL 对桶页与 B+ 页一视同仁：先日志后数据。</p></li><li><p>B+ 管有序；本课用可增长哈希桶做等值访问路径。</p></li><li><p>磁盘哈希要处理分裂与目录，不是内存一张表。</p></li><li><p>页一改如何先记日志，是后课缺口。</p></li><li><p>出处：Fagin et al., 1979；Litwin, 1980；Ramakrishnan and Gehrke。</p></li></ul>',9))])}const x=s(c,[["render",B]]);export{T as __pageData,x as default};
